def components(g):
 h,w=len(g),len(g[0]); seen=set(); result=[]
 for r in range(h):
  for c in range(w):
   if (r,c) in seen: continue
   color=g[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
   for y,x in q:
    cells.append((y,x))
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==color:
      seen.add((yy,xx)); q.append((yy,xx))
   result.append((color,len(cells),min(y for y,x in cells),min(x for y,x in cells),max(y for y,x in cells),max(x for y,x in cells)))
 return sorted(result,key=lambda x:x[1],reverse=True)
